	  IF g_nClylinderCount >= 1 THEN
		SupportCylinder1ForceFlag := TRUE;
	  END_IF;
	  IF g_nClylinderCount >= 2 THEN
		SupportCylinder2ForceFlag := TRUE;
	  END_IF; 
	  IF g_nClylinderCount >= 3 THEN
		SupportCylinder3ForceFlag := TRUE;
