		SupportAxis1ForceFlag := TRUE;
	  END_IF;
	  IF g_nSusutainCount >= 2 THEN
		SupportAxis2ForceFlag := TRUE;
	  END_IF;
	  IF g_nSusutainCount >= 3 THEN
