END_IF;

bForceLimitSpeedFlag := FALSE;

(*六组判断*)
IF bOpenLimit  THEN
	IF g_nClylinderCount >= 1 THEN 
		IF (g_fClylinder1CoordY-g_fCurrentCoordYBuffer < g_fClylinder1DownDistance) AND (g_niMotionType=1 OR g_niMotionType=2 OR  SupportCylinder1ForceFlag) AND g_fCurrentCoordYBuffer < g_fClylinder1CoordY AND g_bClylinder1State THEN
			dDownVel := (g_fClylinder1DownDistance - g_fClylinder1SafeDistance) / FUN_MSTOS(g_dClylinder1DownDoneTime);
			g_doRealtimeOverrid := dDownVel  / dG00YVel * dSupportLimitSpeedPercent;
			IF g_doRealtimeOverrid > 1.0 THEN
				g_doRealtimeOverrid := 1.0;
			ELSIF g_doRealtimeOverrid <= 0.0 THEN
				g_doRealtimeOverrid := 0.1;
			END_IF; 
			bForceLimitSpeedFlag := TRUE;
		END_IF;
		IF NOT g_bClylinder1State  THEN
            SupportCylinder1ForceFlag := FALSE;
		END_IF;
