              dSupportAxis1DownTime:=0.001;
            END_IF;
            g_doRealtimeOverrid := (((g_fSupAxisDownDis1 -  g_fSupAxisSafeDis1) / dSupportAxis1DownTime) / dG00YVel)* dSupportLimitSpeedPercent * (dSupportAxis1AbsVel / dG00YVel) ;
