              dSupportAxis8DownTime:=0.001;
            END_IF;
            g_doRealtimeOverrid := (((g_fSupAxisDownDis8 -  g_fSupAxisSafeDis8) / dSupportAxis8DownTime) / dG00YVel)* dSupportLimitSpeedPercent * (dSupportAxis8AbsVel / dG00YVel) ;
			IF g_doRealtimeOverrid > 1.0 THEN
				g_doRealtimeOverrid := 1.0;
			ELSIF g_doRealtimeOverrid <=  0.0 THEN
				g_doRealtimeOverrid := 0.1;
			END_IF;
			bForceLimitSpeedFlag := TRUE;
		END_IF;
