			dSupportAxis11DownTime := FUN_CALCAXISMOVETIME(g_dSupportAxis11ActPos,0.0,dSupportAxis11AbsVel,dSupportAxis11Acc,dSupportAxis11Jerk);
			IF dSupportAxis11DownTime < 0.001 THEN 
