            g_doRealtimeOverrid := (((g_fSupAxisDownDis11 -  g_fSupAxisSafeDis11) / dSupportAxis11DownTime) / dG00YVel)* dSupportLimitSpeedPercent * (dSupportAxis11AbsVel / dG00YVel) ;
			IF g_doRealtimeOverrid > 1.0 THEN
