	IF g_nSusutainCount >= 12 THEN
		IF g_fCurrentCoordYBuffer >= (g_fSupAxisCoordY12 - g_fSupAxisDownDis12) AND (g_niMotionType=1 OR g_niMotionType=2 OR SupportAxis12ForceFlag) AND g_fCurrentCoordYBuffer < g_fSupAxisCoordY12 AND Axis_S12.NCTOPLC.ACTPOS > 0.01 THEN
			dSupportAxis12DownTime := FUN_CALCAXISMOVETIME(g_dSupportAxis12ActPos,0.0,dSupportAxis12AbsVel,dSupportAxis12Acc,dSupportAxis12Jerk);
